import 'dart:convert';
import 'dart:typed_data';
import 'package:excel/excel.dart';
import 'package:file_picker/file_picker.dart';
import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';

void main()=>runApp(const SangroyaApp());
class SangroyaApp extends StatelessWidget {
 const SangroyaApp({super.key});
 @override Widget build(BuildContext context)=>MaterialApp(title:'SANGROYA FAMILY TREE',debugShowCheckedModeBanner:false,theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xFF315C4B)),useMaterial3:true),home:const FamilyHome());
}
class Member {
 final String name,gender,father,mother,village,occupation,spouse,spouseCity,generation,dob,dod,marriageDate,visitedPlaces,jobType,jobCountry,jobDetails,notes;
 const Member({this.name='',this.gender='',this.father='',this.mother='',this.village='',this.occupation='',this.spouse='',this.spouseCity='',this.generation='',this.dob='',this.dod='',this.marriageDate='',this.visitedPlaces='',this.jobType='',this.jobCountry='',this.jobDetails='',this.notes=''});
 Map<String,dynamic> toJson()=>{'name':name,'gender':gender,'father':father,'mother':mother,'village':village,'occupation':occupation,'spouse':spouse,'spouseCity':spouseCity,'generation':generation,'dob':dob,'dod':dod,'marriageDate':marriageDate,'visitedPlaces':visitedPlaces,'jobType':jobType,'jobCountry':jobCountry,'jobDetails':jobDetails,'notes':notes};
 factory Member.fromJson(Map<String,dynamic> j)=>Member(name:j['name']??'',gender:j['gender']??'',father:j['father']??'',mother:j['mother']??'',village:j['village']??'',occupation:j['occupation']??'',spouse:j['spouse']??'',spouseCity:j['spouseCity']??'',generation:j['generation']??'',dob:j['dob']??'',dod:j['dod']??'',marriageDate:j['marriageDate']??'',visitedPlaces:j['visitedPlaces']??'',jobType:j['jobType']??'',jobCountry:j['jobCountry']??'',jobDetails:j['jobDetails']??'',notes:j['notes']??'');
}
class FamilyHome extends StatefulWidget {const FamilyHome({super.key});@override State<FamilyHome> createState()=>_FamilyHomeState();}
class _FamilyHomeState extends State<FamilyHome>{
 final List<Member> members=[];String status='परिवार की जानकारी जोड़ें';
 @override void initState(){super.initState();load();}
 Future<void> load()async{final p=await SharedPreferences.getInstance();final s=p.getString('members');if(s!=null){try{final a=(jsonDecode(s) as List).map((e)=>Member.fromJson(Map<String,dynamic>.from(e))).toList();if(mounted)setState(()=>members.addAll(a));}catch(_){}}}
 Future<void> save()async{final p=await SharedPreferences.getInstance();await p.setString('members',jsonEncode(members.map((m)=>m.toJson()).toList()));}
 Future<void> edit([int? i])async{final m=await showDialog<Member>(context:context,builder:(_)=>MemberForm(member:i==null?const Member():members[i]));if(m!=null){setState((){if(i==null){members.add(m);}else{members[i]=m;}status='जानकारी सुरक्षित हुई';});await save();}}
 Future<void> importExcel()async{final p=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['xlsx','xls'],withData:true);if(p==null||p.files.single.bytes==null){return;}try{final w=Excel.decodeBytes(p.files.single.bytes!);final added=<Member>[];for(final sh in w.tables.values){if(sh.rows.isEmpty)continue;final h=sh.rows.first.map((c)=>(c?.value?.toString()??'').toLowerCase()).toList();int ix(String s)=>h.indexWhere((x)=>x.contains(s));String v(List<Data?> r,int n)=>n<0||n>=r.length?'':(r[n]?.value?.toString()??'');for(final r in sh.rows.skip(1)){final n=v(r,ix('name'));if(n.trim().isEmpty){continue;}added.add(Member(name:n,gender:v(r,ix('gender')),father:v(r,ix('father')),mother:v(r,ix('mother')),village:v(r,ix('village')),occupation:v(r,ix('occupation')),spouse:v(r,ix('life partner')),spouseCity:v(r,ix('partner city')),generation:v(r,ix('generation')),dob:v(r,ix('date of birth')),dod:v(r,ix('date of death')),marriageDate:v(r,ix('marriage date')),visitedPlaces:v(r,ix('places visited')),jobType:v(r,ix('job type')),jobCountry:v(r,ix('job country')),jobDetails:v(r,ix('job details')),notes:v(r,ix('notes'))));}}setState(()=>members.addAll(added));await save();setState(()=>status='${added.length} records Import हुए');}catch(e){setState(()=>status='Excel error: $e');}}
 Future<void> template()async{final x=Excel.createExcel();final s=x['Family Members'];const h=['Name','Gender','Father','Mother','Village','Occupation','Life Partner','Life Partner City','Generation','Date of Birth','Date of Death','Marriage Date','Places Visited','Job Type','Job Country','Job Details','Notes'];s.appendRow(h.map((v)=>TextCellValue(v)).toList());s.appendRow(['नाम','पुरुष/महिला','पिता','माता','गाँव/शहर','पेशा','जीवनसाथी','शहर','1','DD-MM-YYYY','DD-MM-YYYY','DD-MM-YYYY','शहर/देश','Domestic/International','देश','कंपनी, पद, काम','अन्य'].map((v)=>TextCellValue(v)).toList());final b=x.encode();if(b!=null)await FilePicker.platform.saveFile(dialogTitle:'Excel Template सेव करें',fileName:'Sangroya_Family_Tree_Template.xlsx',bytes:Uint8List.fromList(b));}
 void tree()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>FamilyTreePage(members:members)));
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('SANGROYA FAMILY TREE')),floatingActionButton:FloatingActionButton.extended(onPressed:()=>edit(),icon:const Icon(Icons.person_add),label:const Text('Member जोड़ें')),body:ListView(padding:const EdgeInsets.all(14),children:[Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(children:[const Text('18 पीढ़ियों का डिजिटल Family Tree',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),Wrap(spacing:8,children:[FilledButton(onPressed:tree,child:const Text('Family Tree')),OutlinedButton(onPressed:template,child:const Text('Excel Template Download')),OutlinedButton(onPressed:importExcel,child:const Text('Excel Upload'))]),Text('कुल सदस्य: ${members.length}')]))),Text(status),const Text('सदस्य सूची — Edit/Profile के लिए नाम पर क्लिक करें'),...members.asMap().entries.map((e)=>Card(child:ListTile(title:Text(e.value.name),subtitle:Text([e.value.gender,e.value.village,e.value.father].where((x)=>x.isNotEmpty).join(' • ')),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>ProfilePage(member:e.value,all:members))),trailing:IconButton(icon:const Icon(Icons.edit),onPressed:()=>edit(e.key))))),const SizedBox(height:70)]));
}
class MemberForm extends StatefulWidget{final Member member;const MemberForm({super.key,required this.member});@override State<MemberForm> createState()=>_MemberFormState();}
class _MemberFormState extends State<MemberForm>{
 late final Map<String,TextEditingController> c;late String gender,job;
 @override void initState(){super.initState();final m=widget.member;gender=m.gender.isEmpty?'पुरुष':m.gender;job=m.jobType.isEmpty?'Domestic':m.jobType;c={'name':m.name,'father':m.father,'mother':m.mother,'village':m.village,'occupation':m.occupation,'spouse':m.spouse,'spouseCity':m.spouseCity,'generation':m.generation,'dob':m.dob,'dod':m.dod,'marriageDate':m.marriageDate,'visitedPlaces':m.visitedPlaces,'jobCountry':m.jobCountry,'jobDetails':m.jobDetails,'notes':m.notes}.map((k,v)=>MapEntry(k,TextEditingController(text:v)));}
 @override void dispose(){for(final x in c.values){x.dispose();}super.dispose();}
 Widget f(String k,String label,{int lines=1})=>Padding(padding:const EdgeInsets.only(bottom:8),child:TextField(controller:c[k],maxLines:lines,decoration:InputDecoration(labelText:label,border:const OutlineInputBorder())));
 @override Widget build(BuildContext context)=>AlertDialog(title:Text(widget.member.name.isEmpty?'नया सदस्य':'Member Edit करें'),content:SizedBox(width:500,child:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[f('name','पूरा नाम'),DropdownButtonFormField(initialValue:gender,decoration:const InputDecoration(labelText:'लिंग'),items:const [DropdownMenuItem(value:'पुरुष',child:Text('पुरुष / Male')),DropdownMenuItem(value:'महिला',child:Text('महिला / Female')),DropdownMenuItem(value:'अन्य',child:Text('अन्य'))],onChanged:(v){if(v!=null)setState(()=>gender=v);}),const SizedBox(height:8),f('father','पिता का नाम'),f('mother','माता का नाम'),f('village','गाँव / जन्म स्थान'),f('dob','Date of Birth DD-MM-YYYY'),f('dod','Date of Death DD-MM-YYYY'),f('spouse','जीवनसाथी का नाम'),f('spouseCity','जीवनसाथी का शहर'),f('marriageDate','Marriage Date DD-MM-YYYY'),f('generation','पीढ़ी संख्या'),f('occupation','पेशा / पद'),DropdownButtonFormField(initialValue:job,decoration:const InputDecoration(labelText:'Job Type'),items:const [DropdownMenuItem(value:'Domestic',child:Text('Domestic — भारत')),DropdownMenuItem(value:'International',child:Text('International — विदेश')),DropdownMenuItem(value:'लागू नहीं',child:Text('लागू नहीं'))],onChanged:(v){if(v!=null)setState(()=>job=v);}),if(job=='International')f('jobCountry','किस देश में नौकरी?'),f('jobDetails','Job Details — कंपनी, पद, शहर, अवधि',lines:3),f('visitedPlaces','कहाँ-कहाँ Visit किया',lines:2),f('notes','अन्य जानकारी',lines:2)]))),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Cancel')),FilledButton(onPressed:(){if(c['name']!.text.trim().isEmpty)return;String v(String k)=>c[k]!.text.trim();Navigator.pop(context,Member(name:v('name'),gender:gender,father:v('father'),mother:v('mother'),village:v('village'),occupation:v('occupation'),spouse:v('spouse'),spouseCity:v('spouseCity'),generation:v('generation'),dob:v('dob'),dod:v('dod'),marriageDate:v('marriageDate'),visitedPlaces:v('visitedPlaces'),jobType:job,jobCountry:v('jobCountry'),jobDetails:v('jobDetails'),notes:v('notes')));},child:const Text('Save'))]);
}
class ProfilePage extends StatelessWidget{
 final Member member;final List<Member> all;const ProfilePage({super.key,required this.member,required this.all});
 List<Member> named(String n)=>all.where((m)=>m.name.toLowerCase().trim()==n.toLowerCase().trim()).toList();
 List<Member> kids(String n)=>all.where((m)=>m.father.toLowerCase().trim()==n.toLowerCase().trim()).toList();
 Widget row(String k,String v)=>v.isEmpty?const SizedBox.shrink():ListTile(title:Text(k),subtitle:Text(v));
 @override Widget build(BuildContext context){final f=named(member.father);final g=f.length==1?named(f.first.father):<Member>[];final sons=kids(member.name);final grand=sons.expand((m)=>kids(m.name)).toList();return Scaffold(appBar:AppBar(title:Text(member.name)),body:ListView(padding:const EdgeInsets.all(12),children:[Card(child:Column(children:[row('लिंग',member.gender),row('जन्म तिथि',member.dob),row('मृत्यु तिथि',member.dod),row('जन्म स्थान',member.village),row('पिता',member.father),row('माता',member.mother),row('दादा',g.length==1?g.first.name:'रिकॉर्ड नहीं मिला') ])),Card(child:Column(children:[row('जीवनसाथी',member.spouse),row('जीवनसाथी का शहर',member.spouseCity),row('विवाह तारीख',member.marriageDate)])),Card(child:Column(children:[row('पेशा',member.occupation),row('Job Type',member.jobType),row('देश',member.jobCountry),row('Job Details',member.jobDetails),row('Visited Places',member.visitedPlaces)])),Card(child:Column(children:[const ListTile(title:Text('तीन पीढ़ियों का विवरण')),row('पुत्र / पुत्रियाँ',sons.map((m)=>m.name).join(', ')),row('पोते / पोतियाँ',grand.map((m)=>m.name).join(', '))]))]));}
}
class FamilyTreePage extends StatelessWidget{final List<Member> members;const FamilyTreePage({super.key,required this.members});@override Widget build(BuildContext context){final counts=<String,int>{};for(final m in members){final k=m.name.toLowerCase().trim();counts[k]=(counts[k]??0)+1;}final map=<String,List<Member>>{};for(final m in members){final k=m.father.toLowerCase().trim();if(k.isNotEmpty&&counts[k]==1)map.putIfAbsent(k,()=>[]).add(m);}final roots=members.where((m){final k=m.father.toLowerCase().trim();return k.isEmpty||counts[k]!=1;}).toList();return Scaffold(appBar:AppBar(title:const Text('Family Tree — 18 पीढ़ियाँ')),body:ListView(padding:const EdgeInsets.all(12),children:[const Text('किसी भी सदस्य पर क्लिक करके पिता, दादा, बच्चों और पोते-पोतियों का विवरण देखें।'),...roots.map((m)=>TreeNode(m:m,map:map,all:members,path:<String>{},depth:1))]));}}
class TreeNode extends StatelessWidget{final Member m;final Map<String,List<Member>> map;final List<Member> all;final Set<String> path;final int depth;const TreeNode({super.key,required this.m,required this.map,required this.all,required this.path,required this.depth});@override Widget build(BuildContext context){final k=m.name.toLowerCase().trim();final p={...path,k};final kids=(map[k]??[]).where((x)=>!p.contains(x.name.toLowerCase().trim())).toList();final tile=ListTile(title:Text(m.name),subtitle:Text([m.gender,m.village,m.spouse].where((x)=>x.isNotEmpty).join(' • ')),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>ProfilePage(member:m,all:all))));return Card(margin:EdgeInsets.only(left:(depth-1)*10),child:kids.isEmpty?tile:ExpansionTile(title:Text(m.name),subtitle:tile.subtitle,children:kids.map((x)=>TreeNode(m:x,map:map,all:all,path:p,depth:depth+1)).toList()));}}
